+ * \file block_mmad_to_multi_mul.h
+ * \brief
+ */
+
+#pragma once
+#include "./block_mmad.h"
+#include "../utils/layout_utils.h"
+#include "../utils/tuple_utils.h"
+#include "../policy/dispatch_policy.h"
+#include "adv_api/reduce/reduce.h"
