+bool MatMulV3ToVectorTiling::IsCapable()
+{
+    // 未使能高精度模式
+    if (!args_.isForceGrpAccForFp32) {
+        return false;
+    }
+    // !ATrans && BTrans
+    if (args_.isATrans || !args_.isBTrans) {
+        return false;
+    }
+    // 暂时不支持bias
+    if (args_.hasBias) {
+        return false;
+    }
+    if (args_.aDtypeSize != sizeof(float) || args_.bDtypeSize != sizeof(float)) {
+        return false;
+    }
+    return true;
+}
